import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {};
  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const surface = colors.surface ?? '#0b0b10';

  const root = new Group();
  root.name = config.id ?? 'collection-card-3';

  const geometries = [];
  const materials = [];
  const textures = [];
  const primitiveCleanups = [];
  let disposed = false;

  const makePlane = (width, height, material, z) => {
    const geometry = new PlaneGeometry(width, height);
    geometries.push(geometry);
    materials.push(material);

    const mesh = new Mesh(geometry, material);
    mesh.position.z = z;
    root.add(mesh);
    return mesh;
  };

  const gradientMaterial = new MeshBasicNodeMaterial();
  gradientMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    smoothstep(0.0, 1.0, uv().y)
  );
  makePlane(7, 6, gradientMaterial, -2.5);

  const contactMaterial = new MeshBasicNodeMaterial({
    color: surface,
    transparent: true,
    opacity: 0.55
  });
  makePlane(3.1, 1.95, contactMaterial, -0.32);

  const accentMaterial = new MeshBasicNodeMaterial({ color: accent });
  makePlane(2.92, 1.82, accentMaterial, -0.22);

  const imageMaterial = new MeshBasicNodeMaterial({
    color: paper
  });
  const imageMesh = makePlane(2.82, 1.72, imageMaterial, -0.12);

  const imageUrl =
    config.imageUrl ??
    config.intent?.visualSpec?.imageUrl;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }

      textures.push(texture);
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const labelStripMaterial = new MeshBasicNodeMaterial({
    color: surface,
    transparent: true,
    opacity: 0.94
  });
  makePlane(2.82, 0.48, labelStripMaterial, 0.02);

  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  let textIndex = 0;
  for (const item of items) {
    const content = typeof item.text === 'string' ? item.text : '';
    if (!content) continue;

    const textObject = ctx.fontAtlas.createText(content, {
      fontSize: item.typography?.fontSize ?? 39,
      color: paper,
      align: item.role === 'headline' ? 'center' : 'left'
    });

    textObject.position.set(0, -0.77 + textIndex * 0.12, 0.12);
    root.add(textObject);
    textIndex += 1;
  }

  const detailsMaterial = new MeshBasicNodeMaterial({ color: ink });
  const detailsGeometry = new PlaneGeometry(0.06, 0.06);
  geometries.push(detailsGeometry);
  materials.push(detailsMaterial);

  const detail = new Mesh(detailsGeometry, detailsMaterial);
  detail.position.set(1.24, 0.69, 0.04);
  root.add(detail);

  const entrance = gsap.timeline({ paused: false });
  entrance.fromTo(
    root.scale,
    { x: 0.98, y: 0.98, z: 0.98 },
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.7,
      ease: 'power3.out'
    }
  );

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler !== 'function') continue;

    const result = handler(root, primitive.params);
    if (result?.cleanup) primitiveCleanups.push(result.cleanup);
  }

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    entrance.kill();

    for (const cleanup of primitiveCleanups) {
      cleanup();
    }

    for (const texture of textures) {
      texture.dispose?.();
    }

    for (const geometry of geometries) {
      geometry.dispose?.();
    }

    for (const material of materials) {
      material.dispose?.();
    }

    root.traverse((object) => {
      if (object === root) return;
      object.userData?.cleanup?.();
    });
  };

  return root;
}
